    (8, 4, "ወደፈኖሙ ማዕበል ወተሰጥሙ ውስተ ቀላይ ከመ እዳን የማንክ እግዚአ ተሰብሐ በኀይል ፡ የማነ አዴከ እኝ LL, Bt ለፀር።"),
