    (12, 13, "የኢትዮጵያ አርቸዶክስ ተዋሕዶ ቤተ PጓE [ ኦሪት ዛሀአት ወዙሱ ዛነበብዥዀ ዕቀበ\" ' ወስሞሙ ለአማይክተ በዕድ ኢትዝክሩ።"),
