    (12, 20, "ወፍርህተ እፌኑ ቦቱ ለዘይጸንክክ ወይደነሣፁ ዙሁሎሙ ' አሕዛብ ዘቦአክ ኀቤሆሙ ወእሬሲ ዙሎ ረክ ከመ ይኽ | የዬክ።"),
    (12, 21, "5 ወአፌኑ ካያደነግፆሙ ቅድሜካ ለአሞሬዎን ወታወጽ አሙ ለኬጤዎን ወለኤዌዎን ወአከናኔዎን።"),
    (
        12,
        22,
        "አሪት ዘፀአት ' ምዕ ወኢያወክኦሙ በአሐቲ ዓመት ከመ አ-ትኩን ምድር ነ ወከመ ኢ.ይብዝ ላዕሴክ አራዊተ ገዳም = ' \"በበንስቲት አወፅአሙ እምሄከክ እስከ TAX ወት ወርሳ ‘ለምድር = ወክአሰፍሕ ጸድዋለክ እም በሕረ ኤርትራ. አስከ ፍልስ የኤም ወእም ገዳም እስከ ፈለግ ሀሲይ ፈስገ ኤፍራኖክ ወእሜጡ ውስተ አዴከ አለ ይነብሩ ውስተ ምድር ወhወ } ክአሙ አምኔክ x Pn ወኢታኅድሮሙ ወለአማልክቲሆሙ ኢ.ትትአዘዝ።",
    ),
    (12, 23, "ወኢይደንበሩ ውስተ ምድርክ ከመ ኢይግበሩክከ ተአ ብስ ወለኣመ አምለከ አማልክቲሆሙ እሙንቱ ይከውኑክ ' ዕቅፍጥ።"),
    (
        12,
        24,
        "ወይቤሎ እግዚአብሔር ለሙሴ ዕርግ አንተ ወአሮን ወናጓኝብ ወአብዬድ ወመላህቅተ ሕዝብ ሰብዓ እም አስራኡል ወይስግዱ ሊተ እምርተቅ = ወቅረብ አንተ በሕቲተክ ወአሙንቱለሰ ኢይቅረቡ |. ወሕዝብሂ ኢይዕርጉ ምስሌሆሙ = ወበአ ሙሴ ወአይድዐ ስሕዝብ ዙሎ ቃለ እግዚአብ ሔር ወጽድቁ ወአውሥኡ ዙሉ ሕዝብ በአሐዱ ቃል .ወይ ቤሉ ኵሎ ቃለ ዘነበበ እግዚአብሔር ንገብር ወንሰምፅ = ወጸሐፈ ሙሴ ዙሎ ቃለ እግዚአብሔር ወተንሥአ በጽባሕ ወሐነጸጾ ምሥዋፀ ታሕተ ድብር በiወሄ አእበን በጐልዬ ፲ወ፪ ሕዝበ እስራኤል = ወፈነወ ወራዙቶሙ ለውሉደ አስራኤል ወአኣዕረጉ መሥዋስተ መጀዩኃነኒት ለአግዚአብሔር አልሕምተ = ወነሥእ ሙሌ መንፈቀ ደሙ ወአንበረ ውስተ መቅ ለድ፡ ወመንፉቀ ደሙ ከዐወ ላዕለ መሥዋዕት።",
    ),
    (12, 25, '. ወነሥአ ሙሴ መጽሐፈ ሕግ ወአን በበ በፅዝ፣ ሕዝብ - ወይበሉ ስ" ዝነቢበ -ክግዚርሎብር ንገብር ወንሰም።'),
