        "ከመ ኢ-ፎቨሉ ግዳጽ በእኩይ አው ጽኣሙ ' hm \"ቅ ' ሎሙ - በውስት አድባር’ወከመ ያጥዊጽሙ እምድር ih h ርር መቅተክ ዘተቱማዕከ ወመ ዙን ላዕ ኣከዮሙ ስሕ }) ዝብከ።",
