    (21, 2, "| ወለለአሐት ዓፀድ ኑት ሠላስ በኣክመታ ፡ ወርኅቡ ርብፅ በአመት , ለለአሐጽ ዓፀድ ከማሁ በአምጣኒሆሙ።"),
