    (21, 4, "ወገብሩ ገም መማስጠ ላዕለ ከንፈረ አሐዱ ዓፀድ በጽንፉ በዛየግብሩ።"),
    (21, 5, "ወሣምለ መማስጠ ግብ ላዕለ ከንፈረ ዓፀድ ከልእ | በዘየጓሣብሩ 5 ወገብሩ . ሣምስ ይኩን አሐደ።"),
