    (21, 12, "ወክልኤተ አዕማደ ንብ Ly ስመኝዝነ ተብተራ እም ድግር ወፅሩየ ከኑ ወግሣብሩ አመታሕቱ አስከ ላዕሉ ወከማሁ ገብሩ ለክልኤሆን መዓዝን።"),
