    (
        21,
        14,
        ".. ወገብሩ መናሥግተ ለክቃማጅ ደብተራ hap ዘጺ ይነቅዝ - Rg NT ም | - Fr የኢትዮጵያ አርቶዶክስ ተዋሕዶ ቤተ ሣም ስቱ መናሥግተ እምአሐዱ ገጽ ወኀምስተ መናሥ ሣግ አምክልሕ ገጽ መሣምስትተ መና ሥግተ ዘመንገለ. ባሕር።",
    ),
    (21, 15, "ወገብሮ ለመንሠግ ዘማእክል ከመ ይዕዱ ማእከለ ኣቃማድ እምጽጌፍ ግበ ጽንፍ።"),
    (21, 16, "ወለአፅማድ Re ወለመናመሥ ግፔሁ ቀፈል ዎሙ ወርቁ።"),
