    (22, 6, "ወገብረ ላቲ ዐፀደ ለደብተራ መንገለ አዜብ እንተ እ. በስሙ ኪያሁ ፍሉቫ. ሰሴዳ የማን ወመንጦላዕተ ዓፀድ አምቪቢምስ ክዑብ ወኑ ምክ . ት በአመት።"),
